    "依步道長度估算（標示「估」，僅供參考": "길이로 추정('est.'로 표시, 참고용)", "路面・季節・交通": "표면·계절·운송", "體力普通的一般人": "평균적인 체력을 가진 사람이라면 누구나",
    "1 天以內": "1일 이내", "有健行經驗、體力較佳者": "체력이 좋고 경험이 풍부한 등산객", "一般大眾、親子同遊": "일반 대중 및 가족",
    "受過訓練的登山者": "훈련받은 산악인", "3 天以上": "3일 이상", "1 天或 1～3 天": "1일 또는 1~3일",
    "所有人，含長輩、嬰幼兒車": "포함하여 모든 사람 노인 및 유모차", "多日行程": "여러 날 여행", "輕裝、帶水即可": "가벼운 장비, 물만 가져오세요",
    "有登山經驗者": "경험이 풍부한 산악인", "完整登山與過夜裝備": "완전한 등반 및 야간 장비", "齊全登山裝備、禦寒衣物": "완전한 등산 장비 및 따뜻한 레이어",
    "輕裝、帶水與少許糧食": "가벼운 장비, 물, 간식", "受過雪地訓練的登山者": "눈 훈련을 받는 등산객들", "過夜裝備、足夠飲水食物": "야간 장비, 충분한 음식과 물",
    "雪攀裝備（冰斧、冰爪等）": "스노우 장비(얼음 도끼, 아이젠…)", "交通方便、路面好走、設施完善，半天到一天就能輕鬆走完。": "쉬운 접근, 좋은 표면, 완벽한 시설 — 반나절에서 하루 안에 완료됩니다.", "坡度稍陡或有少數比較難走的路段，但設施完善、路面平整，一天內可完成。": "약간 가파르거나 몇 개의 거친 지점이 있지만 잘 관리되어 있어 하루 안에 가능합니다.",
    "高海拔、困難或危險路段較多、坡度陡、天氣多變，需要登山經驗與齊全裝備。": "높은 고도, 어렵고 위험한 구간이 많고 가파르고 변덕스러운 날씨에는 경험과 완전한 장비가 필요합니다.", "路面平整、坡度平緩，連娃娃車和輪椅都能通行。": "평평하고 완만한 길 – 유모차와 휠체어 이용이 가능합니다.", "積雪或結冰的高山路線，需要雪地攀登技術與專門裝備。": "눈이 내리거나 얼어붙은 고산 루트에는 눈 등반 기술과 특수 장비가 필요합니다.",
    "偏遠高山（約 3,000 公尺以上），路況不佳、危險路段多，需三天以上，建議專業人員帶領。": "멀리 떨어진 높은 산(3,000m 이상), 열악한 조건, 많은 위험, 3일 이상 — 전문가와 함께 하세요.", "輕裝、帶水與適量糧食": "가벼운 장비, 물, 음식", "霧": "안개",
    "適合：": "을 위한:", "多雲": "구름 많음", "晴": "맑음",
    "陰": "흐림", "晴時多雲": "맑고 구름 조금", "建議裝備：": "기어:",
    "較偏遠，部分路況較差、坡度較陡，海拔約 2,000～3,000 公尺，可能需要過夜準備。": "2,000~3,000m에 달하는 더 먼 곳, 더 거칠고 가파른 곳에서는 밤새 준비가 필요할 수 있습니다.", "凍毛雨": "얼어붙는 이슬비", "小雨": "약한 비",
    "中雨": "비", "大雨": "폭우", "凍雨": "얼어붙는 비",
    "中雪": "눈", "大雪": "폭설", "小雪": "가벼운 눈",
    "陣雨": "소나기", "強陣雪": "폭설", "雷雨": "뇌우",
    "週一": "월", "週二": "화요일", "週三": "수요일",
    "週四": "목", "週五": "금", "週六": "앉았다",
    "週日": "해", "今天": "오늘", "霰": "눈알",
    "強陣雨": "폭우", "雷雨夾雹": "우박을 동반한 뇌우", "霧凇": "수빙 안개",
    "最低": "낮은", "陣雪": "소나기", "毛毛雨": "이슬비",
    "強雷雨": "심한 뇌우", "全台 2100+ 條步道一手掌握。搜尋、分級、記錄、養成，一起走進山林。": "2,100개가 넘는 대만 트레일을 손쉽게 이용할 수 있습니다. 친구를 검색하고, 채점하고, 기록하고, 키우세요.", "準備": "준비",
    "搜尋步道看官方難度分級、真實路線與海拔剖面；還有天氣、周邊人文景點與美食。用『精選主題輯』快速找古道、瀑布、親子路線。": "공식 등급, 실제 경로, 고도 프로필, 날씨, 명소, 인근 음식을 통해 트레일을 검색하세요. 컬렉션을 사용하여 역사적인 경로, 폭포 경로 또는 가족 경로를 빠르게 찾으세요.", "🌤 最適合出發：": "🌤 가기 가장 좋은 날:", "走路就能養寵物！從一顆蛋開始，靠里程進化：🥚→🦊→🐅→🐉。撿果實、每天餵食、提升親密度，走越多牠陪你長越快。": "애완동물을 키우려면 걸어보세요! 알에서 거리에 따라 진화합니다: 🥚→🦊→🐅→🐉. 열매를 모아서 매일 먹이고 유대감을 형성하세요.",
    "出發前可預載離線地圖，山區沒訊號也看得到；收藏步道、行程可一鍵備份，換手機不怕遺失。": "출발하기 전에 오프라인 지도를 미리 로드하세요. 한 번의 탭으로 트레일을 저장하고 여행을 백업하세요. 휴대폰 간에도 안전하게 보호됩니다.", "小隊同行・我是隊長": "팀라이브 · 내가 리더다", "邊走邊記里程、步數、卡路里、爬升與即時海拔曲線；自動暫停、中斷可復原，離線也能用。": "걷는 동안 거리, 걸음 수, 칼로리, 오르막길, 실시간 고도를 추적하세요. 자동 일시 중지, 충돌 복구, 오프라인으로 작동합니다.",
    "模擬：沿此步道路線前進": "이 트레일을 따라 시뮬레이션 중", "記錄中・在路線上": "녹음 · 이동 중", "林業及自然保育署「自然步道使用困難度分級標準」": "산림청 트레일 난이도 기준",
    "分級數字越大代表越難走。等級依": "숫자가 높을수록 더 어렵다는 의미입니다. 성적은 다음과 같습니다", "小隊同行": "팀 라이브", "全台概覽地圖可離線看了": "이제 대만 개요가 오프라인으로 작동합니다.",
    "更新失敗": "업데이트 실패", "無法開啟": "열 수 없음", "一階階進化 —— 走路的里程、餵食、每日任務與好友送的果實，都會讓牠成長。": "걷기, 먹이 주기, 일일 퀘스트, 친구의 열매 등이 모두 성장에 도움이 됩니다.",
    "是另一個獨立標記（不是難度等級）：代表這條步道": "등급이 아닌 별도의 배지입니다. 이는 이 트레일이", "翻譯年糕": "번역", "餐飲": "음식",
    "資料來源：OpenStreetMap 貢獻者（社群步道，詳細資料有限": "출처: OpenStreetMap 기여자(커뮤니티 트레일, 제한된 세부 정보)", "（我）": "(나)", "（無）": "(없음)",
    "🏪 超商": "🏪 매장", "🚻 廁所": "🚻 화장실", "此步道範圍可離線看地圖了": "이 트레일의 영역은 이제 오프라인으로 작동합니다",
    "美食功能尚未設定（需在 Render 設定 GOOGLE_PLACES_KEY": "음식 검색이 구성되지 않았습니다(GOOGLE_PLACES_KEY 설정).", "景點功能尚未設定（需在 Render 設定 GOOGLE_PLACES_KEY": "명소가 구성되지 않았습니다(GOOGLE_PLACES_KEY 설정).", "（無名）": "(이름 없음)",
