    "受過雪地訓練的登山者": "Alpinisti con allenamento sulla neve", "受過訓練的登山者": "Alpinisti preparati", "輕裝、帶水與適量糧食": "Attrezzatura leggera, acqua e cibo",
    "有登山經驗者": "Alpinisti esperti", "路面平整、坡度平緩，連娃娃車和輪椅都能通行。": "Percorsi pianeggianti e delicati: adatti a passeggini e sedie a rotelle.", "完整登山與過夜裝備": "Attrezzatura completa per arrampicata e pernottamento",
