    "凍雨": "Pioggia gelata", "小雪": "Neve leggera", "中雪": "Nevicare",
    "大雪": "Forte neve", "坡度稍陡或有少數比較難走的路段，但設施完善、路面平整，一天內可完成。": "Leggermente ripido o con alcuni tratti accidentati, ma ben tenuto, fattibile in una giornata.", "交通方便、路面好走、設施完善，半天到一天就能輕鬆走完。": "Facile accesso, buona superficie, servizi completi: tutto in mezza giornata o in un giorno.",
    "較偏遠，部分路況較差、坡度較陡，海拔約 2,000～3,000 公尺，可能需要過夜準備。": "In alcuni punti più remoti, accidentati e ripidi, circa 2.000–3.000 m, potrebbe essere necessaria una preparazione notturna.", "陣雨": "Rovesci", "積雪或結冰的高山路線，需要雪地攀登技術與專門裝備。": "Percorsi alpini innevati o ghiacciati: sono necessarie abilità di arrampicata sulla neve e attrezzatura speciale.",
    "偏遠高山（約 3,000 公尺以上），路況不佳、危險路段多，需三天以上，建議專業人員帶領。": "Montagne remote e remote (oltre 3.000 m), condizioni sfavorevoli, molti pericoli, più di 3 giorni: affidati a professionisti.", "高海拔、困難或危險路段較多、坡度陡、天氣多變，需要登山經驗與齊全裝備。": "Alta quota, molti tratti difficili/pericolosi, tempo ripido e variabile: richiede esperienza e attrezzatura completa.", "雷雨": "Temporali",
    "週一": "Lun", "週二": "Mar", "週三": "Mercoledì",
    "週四": "Gio", "強陣雪": "Forti nevicate", "霧凇": "Nebbia di brina",
    "週五": "Ven", "霰": "Granelli di neve", "週日": "Sole",
    "今天": "Oggi", "最低": "Basso", "週六": "Sab",
    "強陣雨": "Docce forti", "陣雪": "Rovesci di neve", "🌤 最適合出發：": "🌤 Il giorno migliore per partire:",
    "雷雨夾雹": "Temporale con grandine", "小隊同行": "Squadra in diretta", "強雷雨": "Forte temporale",
    "準備": "Pronto", "全台 2100+ 條步道一手掌握。搜尋、分級、記錄、養成，一起走進山林。": "Oltre 2.100 sentieri di Taiwan a portata di mano. Cerca, valuta, registra e alleva il tuo amico.", "邊走邊記里程、步數、卡路里、爬升與即時海拔曲線；自動暫停、中斷可復原，離線也能用。": "Tieni traccia della distanza, dei passi, delle calorie, dell'ascesa e dell'altitudine in tempo reale mentre cammini. Pausa automatica, ripristino in caso di arresto anomalo, funziona offline.",
    "走路就能養寵物！從一顆蛋開始，靠里程進化：🥚→🦊→🐅→🐉。撿果實、每天餵食、提升親密度，走越多牠陪你長越快。": "Cammina per allevare un animale domestico! Da un uovo si evolve con la tua distanza: 🥚→🦊→🐅→🐉. Raccogli le bacche, dagli da mangiare ogni giorno e lega.", "搜尋步道看官方難度分級、真實路線與海拔剖面；還有天氣、周邊人文景點與美食。用『精選主題輯』快速找古道、瀑布、親子路線。": "Cerca sentieri con gradi ufficiali, percorsi reali e profili altimetrici, oltre a meteo, attrazioni e cibo nelle vicinanze. Utilizza le raccolte per trovare rapidamente percorsi storici, a cascata o per famiglie.", "模擬：沿此步道路線前進": "Simulazione lungo questo percorso",
    "小隊同行・我是隊長": "Team Live · Sono il leader", "出發前可預載離線地圖，山區沒訊號也看得到；收藏步道、行程可一鍵備份，換手機不怕遺失。": "Precarica le mappe offline prima di partire. Salva percorsi ed esegui il backup dei viaggi con un solo tocco: in tutta sicurezza su tutti i telefoni.", "一階階進化 —— 走路的里程、餵食、每日任務與好友送的果實，都會讓牠成長。": "e si evolve fase dopo fase: camminare, nutrirsi, le missioni quotidiane e le bacche degli amici lo aiutano a crescere.",
    "記錄中・在路線上": "Registrazione · sul percorso", "全台概覽地圖可離線看了": "La panoramica di Taiwan ora funziona offline", "分級數字越大代表越難走。等級依": "I numeri più alti significano più difficile. Seguono i voti",
    "林業及自然保育署「自然步道使用困難度分級標準」": "Difficoltà sentiero standard del Corpo Forestale", "翻譯年糕": "Traduci", "更新失敗": "Aggiornamento non riuscito",
