    "附近人文景點": "Attrazioni vicine", "篇": "post", "與小隊同行（記錄地圖上看到彼此定位）": "Team Live (guardatevi sulla mappa di registrazione)",
    "👑 隊長（小隊建立者）才能開始記錄；全員在記錄頁按「✋ 準備」後，隊長按開始即全隊一起記錄。": "👑 Può iniziare solo il leader (creatore della squadra). Una volta che tutti hanno toccato \"Pronto\" nella scheda Registra, l'inizio del leader inizia a registrare per l'intero team.", "隱私與設定": "Privacy e impostazioni", "路線檔": "File GPX",
