    "小隊記錄由隊長結束": "Il caposquadra conclude l'escursione", "模擬已走完整條路線，按「⏹ 結束」看結算": "La simulazione ha terminato il percorso: tocca \"⏹ Fine\" per il riepilogo", "緩": "Gentile",
