    "Premium：無限下載": "Премиум: неограниченное скачивание", "隱私與設定": "Конфиденциальность и настройки", "m 下降": "м · Спуск",
    "路線檔": "GPX-файл", "重新整理": "Обновить", "👑 隊長（小隊建立者）才能開始記錄；全員在記錄頁按「✋ 準備」後，隊長按開始即全隊一起記錄。": "👑 Стартовать может только лидер (создатель команды). Как только все нажмут «Готово» на вкладке «Запись», старт лидера начнет запись для всей команды.",
