    "霧": "หมอก", "較偏遠，部分路況較差、坡度較陡，海拔約 2,000～3,000 公尺，可能需要過夜準備。": "ในสถานที่ห่างไกล ขรุขระกว่า และชันกว่า ประมาณ 2,000–3,000 ม. — อาจต้องเตรียมการข้ามคืน", "積雪或結冰的高山路線，需要雪地攀登技術與專門裝備。": "เส้นทางอัลไพน์ที่เต็มไปด้วยหิมะหรือน้ำแข็ง — ต้องใช้ทักษะการปีนหิมะและอุปกรณ์พิเศษ",
    "高海拔、困難或危險路段較多、坡度陡、天氣多變，需要登山經驗與齊全裝備。": "ระดับความสูง พื้นที่ยากลำบาก/อันตรายมากมาย สภาพอากาศที่สูงชันและเปลี่ยนแปลงได้ — ต้องการประสบการณ์และอุปกรณ์ครบครัน", "中雨": "ฝน", "坡度稍陡或有少數比較難走的路段，但設施完善、路面平整，一天內可完成。": "สูงชันเล็กน้อยหรือมีจุดขรุขระเล็กน้อย แต่ได้รับการดูแลอย่างดี สามารถทำได้ภายในวันเดียว",
