    "搜尋步道看官方難度分級、真實路線與海拔剖面；還有天氣、周邊人文景點與美食。用『精選主題輯』快速找古道、瀑布、親子路線。": "ค้นหาเส้นทางด้วยคะแนนอย่างเป็นทางการ เส้นทางจริง และโปรไฟล์ระดับความสูง รวมถึงสภาพอากาศ สถานที่ท่องเที่ยว และอาหารในบริเวณใกล้เคียง ใช้คอลเลกชั่นเพื่อค้นหาเส้นทางประวัติศาสตร์ น้ำตก หรือเส้นทางครอบครัวอย่างรวดเร็ว", "強陣雨": "ฝนตกหนัก", "陣雪": "หิมะตกปรอยๆ",
