    "小隊同行・我是隊長": "ทีมไลฟ์ · ฉันเป็นผู้นำ", "準備": "พร้อม", "強雷雨": "พายุฝนฟ้าคะนองรุนแรง",
    "🌤 最適合出發：": "🌞 วันที่ดีที่สุดที่ควรไป:", "模擬：沿此步道路線前進": "จำลองตามเส้นทางนี้", "林業及自然保育署「自然步道使用困難度分級標準」": "มาตรฐานความยากของเส้นทางกรมป่าไม้",
    "走路就能養寵物！從一顆蛋開始，靠里程進化：🥚→🦊→🐅→🐉。撿果實、每天餵食、提升親密度，走越多牠陪你長越快。": "เดินเลี้ยงสัตว์เลี้ยง! จากไข่ มันจะวิวัฒนาการตามระยะห่างของคุณ: 🥚→🦊→🐅→🐉 เก็บผลเบอร์รี่ ให้อาหารทุกวันและผูกพัน", "出發前可預載離線地圖，山區沒訊號也看得到；收藏步道、行程可一鍵備份，換手機不怕遺失。": "โหลดแผนที่ออฟไลน์ล่วงหน้าก่อนเดินทาง บันทึกเส้นทางและสำรองข้อมูลการเดินทางด้วยการแตะเพียงครั้งเดียว — ปลอดภัยบนโทรศัพท์", "記錄中・在路線上": "การบันทึก · บนเส้นทาง",
    "分級數字越大代表越難走。等級依": "ตัวเลขที่สูงขึ้นหมายถึงยากขึ้น เกรดตามมา.", "小隊同行": "ทีมถ่ายทอดสด", "是另一個獨立標記（不是難度等級）：代表這條步道": "เป็นตราแยก (ไม่ใช่เกรด) หมายความว่าเส้นทางนี้เป็น",
