    "到「記錄」分頁開始你的第一條路線": "Bắt đầu lộ trình đầu tiên của bạn trên tab Ghi", "星級": "Ngôi sao", "還沒有可顯示的軌跡，先去走一條吧": "Chưa có đường đi nào - hãy đi bộ một đường!",
