    "👑 隊長結束了小隊記錄，一起看結算": "👑 Trưởng nhóm đã kết thúc chuyến đi bộ đường dài của nhóm - đây là bản tóm tắt của bạn", "出發前仍請留意現場天候與狀況": "Kiểm tra thời tiết và điều kiện tại chỗ trước khi ra ngoài", "小隊記錄由隊長開始：請先按「✋ 準備」，等隊長按開始": "Người lãnh đạo bắt đầu ghi nhóm — chạm vào “✋ Sẵn sàng” và đợi",
