    "大雪": "Salju lebat", "雪攀裝備（冰斧、冰爪等）": "Perlengkapan salju (kapak es, crampon…)", "過夜裝備、足夠飲水食物": "Perlengkapan semalam, banyak makanan & air",
    "齊全登山裝備、禦寒衣物": "Perlengkapan pendakian gunung lengkap & lapisan hangat", "晴時多雲": "Sebagian besar cerah", "霧凇": "kabut waktu",
    "雷雨": "Badai petir", "偏遠高山（約 3,000 公尺以上），路況不佳、危險路段多，需三天以上，建議專業人員帶領。": "Pegunungan tinggi terpencil (3.000 m+), kondisi buruk, banyak bahaya, 3+ hari — pergilah bersama profesional.", "積雪或結冰的高山路線，需要雪地攀登技術與專門裝備。": "Rute pegunungan bersalju atau dingin — memerlukan keterampilan memanjat salju dan peralatan khusus.",
